update cw_category set parent_id=#{parentId}, category_name=#{categoryName}, slug=#{slug},
    icon=#{icon}, cover_url=#{coverUrl}, video_url=#{videoUrl}, poster_url=#{posterUrl},
    heading_image=#{headingImage}, sort_order=#{sortOrder}, status=#{status},
    article_style=#{articleStyle}, hidden=#{hidden}, update_by=#{updateBy}, update_time=sysdate(), remark=#{remark}
where category_id=#{categoryId}

mapper.select:


    and p.post_title like concat('%', #{postTitle}, '%')
    and (p.category_id=#{categoryId} or find_in_set(#{categoryId}, p.category_ids))
    and p.format=#{format}
    and p.status=#{status}

order by p.featured desc, p.sort_order asc, p.publish_time desc, p.post_id desc

mapper.update:
update cw_post set post_title=#{postTitle}, slug=#{slug}, excerpt=#{excerpt}, thumbnail=#{thumbnail},
    format=#{format}, format_content=#{formatContent}, category_id=#{categoryId}, category_ids=#{categoryIds},
    content=#{content}, status=#{status}, featured=#{featured}, sort_order=#{sortOrder}, views=#{views},
    favorite_count=#{favoriteCount}, mode=#{mode}, style=#{style}, publish_time=#{publishTime},
    update_by=#{updateBy}, update_time=sysdate(), remark=#{remark}
where post_id=#{postId}

