update cw_page set page_key=#{pageKey}, page_title=#{pageTitle}, page_name=#{pageName}, slug=#{slug},
    modules_json=#{modulesJson}, config_json=#{configJson}, background_color=#{backgroundColor},
    background_image=#{backgroundImage}, status=#{status}, sort_order=#{sortOrder},
    update_by=#{updateBy}, update_time=sysdate(), remark=#{remark}
where page_id=#{pageId}

update cw_comment set post_id=#{postId}, parent_id=#{parentId}, nickname=#{nickname}, avatar=#{avatar},
    content=#{content}, status=#{status}, update_by=#{updateBy}, update_time=sysdate(), remark=#{remark}
